import type {
  BossBattle,
  GlossaryTerm,
  ReadinessGroup,
  StatusEntry,
  TroubleEntry,
  VersionRow,
} from "./types";

export const GLOSSARY: GlossaryTerm[] = [
  { term: "API (Application Programming Interface)", def: "A contract another program can call. In this course: the NestJS REST endpoints the Next.js frontend consumes." },
  { term: "Authentication (AuthN)", def: "Proving who you are. Supabase Auth issues the tokens; the server verifies them on every request." },
  { term: "Authorization (AuthZ)", def: "Deciding what an authenticated identity may do. Owned by NestJS guards and policy services — never the UI." },
  { term: "Bearer token", def: "A credential sent in the Authorization header ('Bearer <token>'). Whoever bears it claims the identity — so servers verify signatures and expiry, and HTTPS protects it in transit." },
  { term: "Cache-aside", def: "App reads cache first; on miss it reads the database, writes the result to cache with a TTL, and returns it. The workhorse pattern of Phase 27." },
  { term: "Client", def: "The requesting side — usually the browser, but also curl, a worker, or a test. 'Client' describes a role, not a device." },
  { term: "CORS", def: "Cross-Origin Resource Sharing: browser-enforced rules for when a page may call an API on a different origin. Servers opt in with Access-Control-* headers; a preflight OPTIONS request checks first." },
  { term: "CSRF", def: "Cross-Site Request Forgery: tricking a logged-in browser into sending an unwanted request. Mitigated by token-based auth, SameSite cookies, and origin checks." },
  { term: "Database constraint", def: "A rule the database itself enforces (unique email, quantity ≥ 0, foreign keys). The final integrity guard that outlives application code." },
  { term: "Dependency Injection (DI)", def: "Objects receive their collaborators from a container instead of constructing them. NestJS wires services into controllers automatically — you declare, it assembles." },
  { term: "DNS", def: "The phone book that maps domain names to IP addresses. The first stop of every request, and a classic deployment failure point." },
  { term: "DTO (Data Transfer Object)", def: "The typed shape of data crossing a boundary (API request/response). Validated at runtime in NestJS; the frontend's Zod schemas are a separate, UX-facing concern." },
  { term: "Edge / CDN", def: "Servers geographically close to users that cache and serve content. Great for static and public data; authenticated data needs careful cache headers." },
  { term: "Event loop", def: "Node's scheduler: runs your code to completion, then processes queued callbacks (timers, I/O, promises). The reason async code doesn't block the server." },
  { term: "Guard", def: "A NestJS gate that runs before a route handler — the standard place for authentication and authorization decisions." },
  { term: "Hydration", def: "React attaching event handlers and state to server-rendered HTML in the browser. Mismatches between server and client HTML cause hydration errors." },
  { term: "Idempotency", def: "Doing the same operation twice produces the same result as once. Critical for retries, webhooks, and payments — usually enforced with idempotency keys and unique constraints." },
  { term: "Index (database)", def: "A sorted lookup structure that makes specific queries fast at the cost of slower writes and extra storage. EXPLAIN shows whether a query uses one." },
  { term: "Interceptor", def: "NestJS middleware-like layer that wraps route handlers — used for logging, correlation IDs, response shaping, and timeouts." },
  { term: "JWT", def: "JSON Web Token: a signed, base64 package of claims (who, what, until when). Signed means verifiable — servers must verify, never merely decode." },
  { term: "Migration", def: "A versioned, reviewable script that changes the database schema. Prisma Migrations are authoritative for this course's schema — dashboard edits are not." },
  { term: "N+1 query", def: "Fetching a list (1 query) then each item's relations individually (N queries). The classic ORM performance trap, cured by relation loading and joins." },
  { term: "ORM", def: "Object-Relational Mapper: translates typed code into SQL and rows back into objects. Prisma is this course's ORM — backend/worker-only." },
  { term: "Preflight", def: "An automatic OPTIONS request browsers send before certain cross-origin calls to ask permission. If the server's CORS config is wrong, the real request never flies." },
  { term: "REST", def: "An API style modeling resources (nouns) with HTTP methods (verbs), predictable URLs, and status codes — the convention this course's NestJS APIs follow." },
  { term: "RLS (Row Level Security)", def: "Postgres policies that filter rows per request. Taught as defense-in-depth; in this architecture NestJS remains the authoritative policy owner." },
  { term: "Runtime", def: "The engine executing code. Node.js runs JavaScript outside the browser; the browser runs it inside. Same language, different runtimes, different APIs." },
  { term: "Schema", def: "The structure definition: Prisma schema (models, relations) or database schema (tables, columns, constraints). Single source of truth for data shape." },
  { term: "Seed", def: "Scripted starter data (development fixtures, required lookup rows). Reproducible — never hand-typed dashboard rows." },
  { term: "Server Component", def: "A React component that renders on the server and ships no JS to the browser. Default in the Next.js App Router; Client Components ('use client') handle interactivity." },
  { term: "Session", def: "Server-side state tied to an identifier the client presents. JWTs move state into the signed token; sessions keep state server-side. Both answer 'who is this request?'." },
  { term: "SSR / CSR", def: "Server-Side Rendering builds HTML per request on the server; Client-Side Rendering builds it in the browser from JavaScript. Next.js lets you choose per route/component." },
  { term: "Transaction", def: "A group of database operations that all succeed or all fail (ACID). The tool that keeps 'debit AND credit, or neither' true under concurrency." },
  { term: "Trust boundary", def: "A line data crosses where it must be re-validated and re-authorized. Browser → server is the big one; the frontend's job ends at politeness, the server's begins at truth." },
  { term: "Webhook", def: "An external service calling your API when something happens (payment captured, email bounced). Verified with signatures and timestamps; never trusted because 'the redirect looked fine'." },
  { term: "XSS", def: "Cross-Site Scripting: injecting script into pages other users see. React escapes by default; dangerouslySetInnerHTML and raw HTML APIs are the controlled-danger zones." },
  { term: "Worker / queue", def: "A separate process consuming jobs from a queue (BullMQ over Redis) — for email, reports, imports: anything too slow or too important for the request path." },
  { term: "Stack trace", def: "An error's itinerary: top frame is where it threw, frames below are callers, each linking to file:line:column. Read top-down for 'where', bottom-up for 'how it got here'." },
  { term: "Breakpoint / logpoint", def: "A pause marker set on a line in Sources; a logpoint prints expressions on each pass without pausing or editing code. Both beat console.log soup." },
  { term: "Environment variable", def: "A KEY=value pair handed to a process at startup — configuration, not code. Always a string; different in every environment (dev/staging/prod)." },
  { term: ".env / .env.example", def: "The untracked pouch of real values, and the committed map of key names with dummy values. The example teaches the shape; the pouch stays out of Git." },
  { term: "Fail-fast config", def: "Startup validation that throws on missing/empty env vars — misconfiguration dies in milliseconds with the exact name instead of mid-request at 2 a.m." },
  { term: "Secret rotation", def: "Replacing a credential and rolling the new one out. Mandatory the moment a secret is exposed (Git, logs, screenshots); routine hygiene regardless." },
  { term: "Landmark", def: "A navigable page region for assistive tech: banner, navigation, main (exactly one), complementary, contentinfo, region, form, search. The building's signs." },
  { term: "Accessible name", def: "What a control is announced as — from visible text, <label for>, or aria-label. No name means a mystery box for screen readers." },
  { term: "Div soup", def: "A page built from anonymous div/span with behavior bolted on in JS: invisible landmarks, keyboard-dead controls, nameless widgets. The disease semantic HTML cures." },
  { term: "Constraint Validation API", def: "The browser's built-in form engine: required/type/pattern/min/max checked on submit, invalid submissions blocked, first failing field focused and explained — localized, for free." },
  { term: "ValidityState", def: "field.validity: named failure flags (valueMissing, typeMismatch, patternMismatch, rangeUnderflow, tooShort…) plus validationMessage. Ask the engine; never parse strings." },
  { term: "setCustomValidity", def: "Make a field invalid with your own message (cross-field rules like 'passwords match'); pass '' to clear. Keeps custom rules inside the native validation flow." },
  { term: "The cascade", def: "CSS's tie-break order when rules compete: origin → !important → specificity → source order. Per property, always that sequence — 'my style didn't work' has exactly four suspects." },
  { term: "Specificity", def: "A selector's rank as a triplet (IDs · classes · elements), compared left to right. Combinators and * score zero; inline styles beat selectors; :where() scores zero by design." },
  { term: "Box model", def: "Every element: content → padding → border → margin, nested outward. border-box makes width include padding+border; margins always sit outside and never collapse horizontally." },
  { term: "Margin collapse", def: "Adjacent vertical margins in block flow merge to the larger one. Flexbox and Grid children never collapse — a quiet reason modern layout feels predictable." },
  { term: "rem vs em", def: "rem tracks the root font-size (respects user settings — the accessible default); em tracks the current element's font-size (compounds when nested). px only for hairlines." },
  { term: "Flexbox", def: "One-axis layout: items share a line. justify-content works along the axis, align-items across it, wrap handles overflow, gap spaces items. Content-out: the items' sizes negotiate." },
  { term: "Grid", def: "Two-axis layout: define tracks first (columns/rows in fr or minmax), then place items. Layout-in: the map decides where content lives. grid-template-areas sketches whole pages." },
  { term: "fr unit", def: "A share of leftover grid space. 200px 1fr = fixed rail + fluid column; 1fr 2fr splits leftovers 1:2 after fixed tracks. Unlike %, it accounts for siblings." },
  { term: "auto-fill + minmax", def: "repeat(auto-fill, minmax(min(100%, Xpx), 1fr)) — the responsive card-wall pattern: track count follows the container, zero media queries required." },
  { term: "Mobile-first", def: "Default styles serve small screens; @media (min-width: …) adds structure as space appears. Rules accumulate instead of undoing each other." },
  { term: "Reflow (WCAG)", def: "At 200% zoom on a desktop window, content must not require horizontal scrolling. Fluid units and wrapping grids pass; fixed px widths fail." },
  { term: "Design token", def: "A design decision named once (--brand, --surface, --r) and consumed everywhere via var(). Role-based names survive rebrands and themes; appearance names become lies." },
  { term: "Theme mapping", def: "Dark/light as re-declarations of the same token names under [data-theme]. Components never change; one attribute flips the dictionary. Inherits, so subtrees can re-skin independently." },
  { term: "WCAG contrast", def: "4.5:1 minimum for body text, 3:1 for large text and UI parts; 7:1 is AAA. Verify per theme — colored-on-colored pairs are where designs fail." },
  { term: "Coercion", def: "JavaScript converting a value's type on your behalf ('5' + 1 → '51', '5' - 1 → 4). Explicit conversion (Number(), String()) beats letting the engine improvise." },
  { term: "Falsy list", def: "Exactly eight values are falsy: false, 0, -0, 0n, '', null, undefined, NaN. Everything else is truthy — including [], {}, and '0'." },
  { term: "?? (nullish coalescing)", def: "Falls back to the right operand only when the left is null or undefined. Use it instead of || whenever 0 or '' is a valid value." },
  { term: "=== vs ==", def: "=== compares type and value with no coercion. == coerces first (0 == '0' is true). Professional default: === everywhere; x == null is the one sanctioned exception." },
  { term: "Closure", def: "A function bundled with the variables from the scope where it was created. It 'remembers' those variables even after the outer function returns — the basis of private state." },
  { term: "Hoisting", def: "Declarations are registered before their line executes. Function declarations are fully hoisted; var hoists as undefined; let/const sit in the Temporal Dead Zone until their line." },
  { term: "Temporal Dead Zone (TDZ)", def: "The span from the start of a block until a let/const declaration executes. Reading the variable there throws a ReferenceError." },
  { term: "Debounce", def: "Delaying a function until input stops for a set time, restarting on each new input. The standard guard for search-as-you-type and resize handlers." },
  { term: "structuredClone", def: "Built-in deep copy for objects/arrays (unlike spread, which is shallow). Handles nested data, Dates, Maps — but not functions or DOM nodes." },
  { term: "NaN", def: "The 'Not a Number' value, produced by failed numeric operations (Number('abc')). NaN === NaN is false — always test with Number.isNaN()." },
  { term: "map / filter / reduce", def: "The declarative trio: map transforms every element (same length), filter keeps matches (subset), reduce folds everything into one value. None mutate the original." },
  { term: "Mutation vs copy", def: "Mutators (push, splice, sort) change an array in place; copy-makers (map, filter, slice, toSorted) return a new one. React change detection requires copies." },
  { term: "Immutability", def: "Producing new values instead of editing existing ones. React/TanStack Query detect changes via reference identity, so mutated state is invisible to them." },
  { term: "Shallow vs deep copy", def: "Spread copies one level — nested objects are still shared references. structuredClone copies all the way down. Know which you need before you copy." },
  { term: "Reference identity", def: "Whether two variables point at the same object (a === b). Copying creates a new identity; mutating preserves it. The basis of change detection." },
  { term: "Lookup table", def: "An object or Map keyed for O(1) access (bySku[sku]) instead of repeated find() scans. Built from arrays via Object.fromEntries." },
  { term: "The DOM", def: "The browser's live object tree of your HTML. Every element is a JS object you can query (querySelector), restyle, build, and attach listeners to." },
  { term: "Event bubbling", def: "Events fire on the target, then travel up every ancestor to document. Delegation exploits this by listening on a stable parent." },
  { term: "Event delegation", def: "One listener on a stable ancestor + event.target.closest('[data-action]'). Serves unlimited children and survives re-renders that rebuild them." },
  { term: "textContent vs innerHTML", def: "textContent writes inert text — safe for user data. innerHTML parses its string as live HTML — the XSS hole. The boundary is origin, not content." },
  { term: "XSS", def: "Cross-site scripting: user-supplied markup executing in other users' browsers. Vanilla defense: user data enters only via textContent/setAttribute/value." },
  { term: "Render loop", def: "state → render() draws the DOM as a projection → actions produce new state → render() again. The pattern every framework (including React) automates." },
  { term: "Promise", def: "An object representing a value arriving later. States: pending → fulfilled (value) or rejected (reason). Settles exactly once; shareable as a value." },
  { term: "async/await", def: "Syntax over promises. async functions return promises; await pauses the function (not the page) until settlement; rejections become catchable throws." },
  { term: "fetch", def: "The browser's network API. await fetch(url) gives a Response (headers/status); the body needs a second await on .json(). Rejects only on network failure." },
  { term: "response.ok", def: "True for HTTP 200–299. fetch fulfills even on 404/500 — check .ok and throw yourself so HTTP and network errors share one catch path." },
  { term: "Promise.all", def: "Runs promises in parallel; fulfills with all values, rejects fast on the first failure. Turns a waterfall (sum of latencies) into the max latency." },
  { term: "Event loop", def: "The browser's scheduler for one JS thread: run a stack task → drain all microtasks → one macrotask → maybe paint → repeat. Why async feels concurrent." },
  { term: "Microtask vs macrotask", def: "Microtasks (promise .then, queueMicrotask) drain fully after each task; macrotasks (setTimeout, events, I/O) are taken one per round. Promises beat timers." },
  { term: "AbortController", def: "Cancels an in-flight fetch via a signal. abort() rejects it with AbortError — the clean way to drop stale requests in a race." },
  { term: "Unhandled rejection", def: "A rejected promise with no catch. The async version of a swallowed error — browsers warn, and Node can crash on them." },
  { term: "Type inference", def: "The compiler deducing types from initializers, returns, and usage. Default to it; annotate only where it genuinely can't guess." },
  { term: "Annotation", def: "An explicit type you write (let x: string). Needed at edges: empty arrays, function params/returns, vars starting null. Avoid on the obvious." },
  { term: "Structural typing", def: "Types are satisfied by shape, not name. Any object with the right fields matches — which makes typing API responses natural." },
  { term: "Optional field (?)", def: "field?: T means field: T | undefined. Reading it forces you to handle the absent case before using it as T." },
  { term: "Literal type", def: "A type with one value: \"done\", 200, true. Unions of literals encode business rules (Status = \"open\" | \"done\")." },
  { term: "as const", def: "Freezes a value: all properties readonly, all values literal. Turns config objects into precise types you can derive from." },
  { term: "Union type", def: "A | B — a value that's an A or a B. The compiler forces you to handle each member before using member-specific fields." },
  { term: "Narrowing", def: "Control-flow analysis: inside a branch that rules out members (typeof, in, discriminant ===), the type shrinks to the survivors." },
  { term: "Discriminated union", def: "Object types sharing one literal field (status, kind, ok) whose value identifies the shape. The course's default modeling tool." },
  { term: "Result<T>", def: "{ ok: true; data: T } | { ok: false; error: string }. The canonical API-result shape; callers branch on ok and get exactly one side." },
  { term: "never", def: "The type with no values. Used in an exhaustive switch default so an unhandled union member becomes a compile error." },
  { term: "Exhaustiveness checking", def: "Ensuring every union member is handled. Adding a member breaks every switch lacking it — forgetting a case becomes a build failure." },
  { term: "Generic", def: "A type-level parameter — a labeled hole filled per call site. <T>(x: T): T carries the caller's type through the function. The mold, not the sculpture." },
  { term: "Constraint (extends)", def: "<T extends Shape> guarantees listed structure while the rest stays free. K extends keyof T locks a parameter to an object's real keys, killing typo bugs." },
  { term: "Utility types", def: "Type-level transformers: Partial/Required (optionality), Pick/Omit (key selection), Record (maps), ReturnType (extraction), NonNullable, Readonly. Derive views; never duplicate." },
  { term: "strict mode", def: "tsconfig's safety bundle: strictNullChecks, noImplicitAny, useUnknownInCatchVariables, and more. Absence becomes a type; guesses become errors. The course baseline." },
  { term: "noUncheckedIndexedAccess", def: "Makes arr[i] and obj[key] typed as T | undefined, because at runtime they genuinely might be. Every index access becomes a decision, not a hope." },
  { term: "Non-null assertion (!)", def: "user!.email tells the compiler to stop verifying a claim. A loan against truth. Prefer guards, ?? modeling, or restructuring; every surviving ! owes a comment." },
  { term: "import type", def: "Marks a type-only import so the compiler erases the whole statement — no runtime binding is chased. Enforced by verbatimModuleSyntax." },
  { term: "Type predicate (v is T)", def: "A boolean-returning function whose signature narrows: (v: unknown) => v is Todo[]. The bridge from unknown to a concrete type, via proof not cast." },
  { term: "Mapped type", def: "{ [K in keyof T]: … } rebuilds every field of a type by one rule. The machinery behind Partial/Readonly/Record. Modifiers: +?/-?/readonly; as remaps keys." },
  { term: "Indexed access (T[K])", def: "The type of property K on type T: User['name'] = string. In generics, makes a return type follow the key argument." },
  { term: "unknown", def: "The safe any: anything assigns in, but nothing is usable until narrowed (typeof/instanceof/in/predicate). The correct type for untrusted boundaries." },
  { term: "Type assertion (as)", def: "Tells the compiler 'I know more than you' — compile-time only, no runtime validation. Legitimate with a documented reason at true boundaries; never to silence errors." },
  { term: "UI = f(state)", def: "The declarative contract: the UI is a pure function of state. Describe the target; React diffs and patches the DOM. The mental model behind all of React." },
  { term: "JSX", def: "A typed description language compiling to element-building calls. Rules: one root/fragment, expressions in {}, camelCase attributes (className, htmlFor), no statements inside." },
  { term: "Component", def: "A PascalCase pure function: typed props in, JSX description out. PascalCase distinguishes it from built-in elements. Props are read-only." },
  { term: "children (prop)", def: "The JSX between a component's tags — the composition slot. Lets callers supply content while the component supplies chrome; the antidote to prop explosion." },
  { term: "Data down, events up", def: "Props (data) flow parent→child; children report intent by calling callback props handed to them. The state owner decides. The one-way flow under React." },
  { term: "State snapshot", def: "State read during a render is a frozen value for that render. setX requests a new snapshot; it never mutates the current one. Batching coalesces requests." },
  { term: "Batching", def: "React collects all state updates from one event (and, since 18, from timeouts/promises too) and re-renders once. Why three setCount(c+1) calls give +1, not +3." },
  { term: "Functional update", def: "setCount(c => c + 1) — computes from the latest queued value, not the render's snapshot. The fix for stale reads when updates depend on previous state." },
  { term: "Key (React)", def: "Stable identity for list items, used by reconciliation to match old and new elements. Must be unique among siblings and survive reorders — usually an id, not an index." },
  { term: "Reconciliation", def: "React diffs the new element tree against the old and patches only what changed. Elements keep state when type + position (+ key) match; otherwise state resets." },
  { term: "Strict Mode", def: "Dev-only double-invocation of renders/effects that exposes impure renders and missing cleanup. A detector, never something to remove." },
  { term: "Controlled input", def: "value + onChange: React state is the single source of truth for a form field; the input renders the state and reports changes back." },
  { term: "Derived state", def: "A value computable from existing state/props — computed during render, never stored. Storing it creates a synchronization bug class." },
  { term: "Lifting state", def: "Moving state up to the nearest common ancestor so siblings can share it: data flows down as props, updates flow up as callbacks." },
  { term: "Effect (useEffect)", def: "Synchronization with an external system (network, timer, subscription, non-React DOM) after commit. Not a lifecycle event; runs when its dependencies change." },
  { term: "Dependency array", def: "The list of values an effect reads. Omitted = every render; [] = once after mount; [a, b] = when those change (Object.is comparison)." },
  { term: "Effect cleanup", def: "The function an effect returns, run before the next run and on unmount. Cancels subscriptions, timers, in-flight requests — the leak fix." },
  { term: "useRef", def: "A mutable box that survives renders without causing them. DOM handles, timer ids, previous values — the render's private memory." },
  { term: "Context", def: "Values provided once and read by any descendant via useContext — theme, auth, locale. For widely-needed low-churn data, not a state-management substitute." },
  { term: "useReducer", def: "State + a pure reducer: (state, action) => state with a typed action vocabulary. For complex transitions where many setX calls interleave." },
  { term: "useMemo / useCallback", def: "Cache a computed value / a function identity across renders when deps are unchanged. A performance tool for measured wins — not decoration." },
  { term: "useId", def: "Generates a stable, SSR-safe unique id for wiring labels/aria attributes. Never for list keys or styling hooks." },
  { term: "React.memo", def: "Wraps a component to skip re-rendering when its props are Object.is-equal. Only pays when renders are expensive — and needs stable prop identities (hence useCallback)." },
  { term: "React Compiler", def: "React's optimizing compiler that auto-inserts memoization with perfect dep honesty. Shifts the default to plain code + measurement; judgment about what's expensive remains human work." },
  { term: "Memoization spray", def: "Wrapping everything in useMemo/useCallback as hygiene. Adds comparison overhead and lying dep arrays while hiding the unmeasured question: is anything actually expensive?" },
  { term: "useTransition", def: "Marks a state update as interruptible so React can paint urgent work (typing, toggling) first. Returns [isPending, startTransition]. A scheduling tool, not a data layer." },
  { term: "useDeferredValue", def: "Returns the latest value when idle but may return a stale one while urgent work lands. Defers an expensive derived render without extra state. Not debounce." },
  { term: "use", def: "Unwraps a cached Promise (suspending until resolved — needs Suspense + ErrorBoundary) or reads a Context. Callable in conditionals, unlike other hooks." },
  { term: "useActionState", def: "Binds an async form action to state: returns [state, dispatch, isPending]. The action's return becomes the new state; isPending guards double-submits." },
  { term: "useFormStatus", def: "Inside a form descendant, reads { pending, data, method, action }. Lets a submit button show a spinner without lifting state or drilling props." },
  { term: "useOptimistic", def: "Renders a temporary overlay of intent during a pending action; discards it on settle, snapping to committed state. Free structural rollback." },
  { term: "Optimism boundary", def: "Be optimistic only for cheap, reversible intents (likes, reorders). Costly/irreversible actions (payments, deletes) get pending + confirmation instead." },
  { term: "Hook Decision Matrix", def: "Constant? → module scope. Derivable? → compute in render. Paint-relevant + varies? → state. Persists, never painted? → ref. First 'yes' names a value's home." },
  { term: "Custom hook", def: "A use*-named function calling other hooks, returning values/functions — never JSX. Packages reusable logic (state + effects + cleanup), not markup." },
  { term: "Rules of Hooks", def: "Top-level only; React functions only. React tracks hooks by call order, so conditional calls corrupt state. Enforced by eslint-plugin-react-hooks." },
  { term: "Boss Battle", def: "A cumulative gate after a phase: timed broken-code scenarios graded on diagnose → fix → defend, with stated pass criteria and a remediation path. BB-1 is the Hooks Gauntlet." },
  { term: "Props contract", def: "The typed agreement between a component and its callers: required = cannot work without, optional = default is right, variants = discriminated unions. Misuse should not compile." },
  { term: "Compound components", def: "Parent owns state, parts share it through a private context, callers compose markup instead of configuring objects. The Radix/shadcn house style (Accordion, Tabs)." },
  { term: "Controlled vs uncontrolled", def: "Controlled: parent passes value + onChange and owns the field. Uncontrolled: component owns state, seeded by defaultValue. Mature components support both via value !== undefined." },
  { term: "State-ownership map", def: "Derived → nobody; one consumer → local; siblings → nearest common ancestor; broad + low-churn → context; survives renders but never paints → ref. Every value has one home." },
  { term: "Error boundary", def: "A class component that catches render-phase errors in its subtree and swaps in a fallback. Placement is per feature; one root boundary is a polite white screen." },
  { term: "The four escapes", def: "Boundaries don't catch: event handlers, async/effect rejections, SSR errors, or their own render. Each has its own tool (try/catch, .catch, framework UI, nested boundary)." },
  { term: "The Suspense protocol", def: "A component suspends by throwing a cached promise mid-render; React shows the nearest fallback and retries on settle. The promise must live outside render or the curtain never lifts." },
  { term: "React.lazy", def: "Dynamic import() as a suspendable component for route-level code splitting. Call at module scope; preload on hover/focus intent; never lazy the first paint." },
  { term: "The resilience sandwich", def: "ErrorBoundary outside, Suspense inside each risky panel: slow gets a curtain, broken gets a bulkhead, and a broken skeleton is still caught. The way home stays outside every boundary." },
  { term: "The six state homes", def: "Local UI (useState), derived (compute in render), form (provisional), URL (shareable view), server (one cache owner), auth (read-only session). Every value has exactly one legitimate home." },
  { term: "State misplacement", def: "The root of most 'state bugs': server data in local useState, shareable filters outside the URL, derived values stored as facts. Diagnose by asking which home a value lives in." },
  { term: "The optimistic round trip", def: "Intent → provisional overlay → network → commit (the server's value) or rollback + surfaced error. Four beats; the fourth is non-negotiable." },
  { term: "The optimism gate", def: "Only cheap-AND-reversible intents (likes, reorders) earn overlays. Costly or irreversible actions (payments, deletes) get pending + explicit confirmation." },
  { term: "Structural rollback", def: "Revert-by-architecture: useOptimistic overlays and TanStack Query optimistic data unwind on settle automatically. Hand-rolled reverts must be written first, under every failure mode." },
  { term: "Presentation vs ledger", def: "Optimistic values are provisional presentation — never persisted, never computed from, never treated as success. Only committed server state feeds badges, totals, and storage." },
  { term: "Idempotency key", def: "A client-generated key the server stores results against and dedupes, so 'same intent twice' applies exactly once. The Phase 29 answer to retries and double-fires." },
  { term: "The Profiler protocol", def: "Record-why on → record ONE interaction → ranked view → click the slowest bar → 'why did this render?' → climb to the origin. Judged against the ~16ms frame budget." },
  { term: "The three render problems", def: "Too many (render what's visible: virtualize/colocate/split), too often (stable refs, state placement, granularity), too slow (useMemo, move out, shrink input). One cure each; memo only fixes 'too often'." },
  { term: "The memo contract", def: "memo skips a render only if ALL props are Object.is-equal — the parent must supply stable identities (useCallback/useMemo). Memo alone with fresh props is comparison tax with no refund." },
  { term: "The five-step perf workflow", def: "Measure → name the expensive thing → treat the cause → memoize only if still needed → re-measure the same interaction. Step five is the receipt; no receipt, no merge." },
  { term: "Then-vs-Now", def: "Reading legacy React as translation, not history: map each old pattern to its modern equivalent and why it changed, so old code can be modernized rather than copied blindly." },
  { term: "Class → function migration", def: "this.state/setState → useState; lifecycle methods (componentDidMount/WillUnmount) → useEffect with deps; render() → the function body. Behavior preserved, ceremony removed." },
  { term: "HOC / render props", def: "Pre-hooks reuse patterns: a function wrapping a component (HOC) or a function passed as a prop (render prop). Hooks express the same logic with less nesting and clearer data flow." },
  { term: "Design system", def: "Tokens made executable: a set of accessible, token-driven components (Button/Input/Modal) with typed contracts that keep a product visually and behaviorally consistent." },
  { term: "Feature folders", def: "Organizing code by feature (each feature owns its components, hooks, api, tests) rather than by layer (all components/, all hooks/). Scales ownership and scoping." },
  { term: "Accessible Modal", def: "A dialog with focus trapped inside, Escape + overlay-click to dismiss, focus returned on close, and proper role/aria-label. a11y is the contract, not an add-on." },
  { term: "Focus management", def: "Deliberately moving and trapping keyboard focus (into a modal, back on close) so keyboard and screen-reader users never get lost in the DOM." },
  { term: "Token-driven component", def: "A component whose spacing, color, radius, and motion all read from design tokens — so a theme or brand change is a variable remap, not a rewrite." },
  { term: "Legacy translation skill", def: "The ability to read a 2018-era component and produce its current-stable equivalent while keeping behavior identical — essential for any real codebase." },
  { term: "URL parts", def: "scheme://host:port/path?query#fragment. The fragment never reaches the server; query params arrive as strings. A URL is typed data, not a string." },
  { term: "The pre-request journey", def: "DNS (name→IP) → TCP handshake (reliable pipe) → TLS (identity + keys). Paid once per tunnel, then reused — why first requests are slowest." },
  { term: "Connection reuse", def: "HTTP/2 multiplexes many requests over one encrypted tunnel, so warm requests skip DNS/connect/TLS. 'Slow first, fast after' is handshake cost." },
  { term: "TTFB", def: "Waiting for server response: last request byte → first response byte. The backend leg — compute, upstream calls, distance. Not download time." },
  { term: "The four latency suspects", def: "'Slow' = DNS/infra, handshake/infra, TTFB/backend, or download/payload. Longest timing bar first; each has a different owner and fix." },
  { term: "Safe methods", def: "GET/HEAD: read-only, repeatable, cacheable. Clients and CDNs WILL repeat them — a GET that mutates is a landmine." },
  { term: "Idempotent methods", def: "GET/PUT/DELETE: same end-state however many times applied. This property IS the retry license — never auto-retry a POST without an idempotency key." },
  { term: "Status choreography", def: "Each status code triggers a client action: 401 refresh token, 403 surface permission error, 409 refetch/merge, 422 map field errors, 429 back off on Retry-After." },
  { term: "Codes vs body", def: "The status code carries the OUTCOME (machine-readable); the body carries the DETAIL. '200 with error:true' makes caches, proxies, and clients all lie." },
  { term: "The request/response envelope", def: "Request: method line + headers + optional body. Response: status line + headers + body, split at a blank line. Headers are the margin notes that run the web." },
  { term: "Stateless HTTP", def: "No memory between requests — every request is a stranger. Identity is a property of the request (cookie or Authorization header), re-verified each time." },
  { term: "The four cookie locks", def: "HttpOnly (invisible to JS), Secure (HTTPS only), SameSite=Lax (withheld cross-site), Max-Age (expiry). Each missing lock is an open window: XSS theft, sniffing, CSRF, long theft windows." },
  { term: "Session (ledger) model", def: "Server stores identity; the cookie carries only a receipt-id. Instant revocation, sensitive data server-side; costs stateful scale. The hotel key card." },
  { term: "Token (passport) model", def: "Claims travel sealed in a JWT; verification is local and stateless. No revocation before expiry → short access tokens plus a protected, revocable refresh token." },
  { term: "JWT", def: "header.payload.signature in base64url. First two segments are readable encoding; the signature is the only security — a keyed seal only the issuer can produce or verify." },
  { term: "Decode ≠ verify", def: "Decoding a JWT reads the claims (anyone can, including forgeries). Verifying checks the signature against the issuer's key. Display from decoded; decide only from verified." },
  { term: "Access vs refresh token", def: "Access: short-lived passport verified per request. Refresh: session-like revocable receipt that earns new access tokens. Supabase's hybrid (Phase 17)." },
  { term: "Authorization: Bearer", def: "The conventional header for token identity. Never put tokens in URLs (logs/history/Referer leaks). Attached explicitly by your code, unlike cookies' automatic attachment." },
  { term: "Same-origin policy", def: "Any origin may SEND a cross-origin request, but a script may READ the response only if it carries a matching Access-Control-Allow-Origin. Protects users, not servers." },
  { term: "CORS gates reading", def: "The request fires and can succeed server-side; CORS decides whether the script sees the answer. 'Blocked' requests usually aren't blocked writes — check the Network tab." },
  { term: "Preflight (OPTIONS)", def: "Browser-fabricated OPTIONS asking Access-Control-Request-Method/-Headers; answered by Access-Control-Allow-*. JSON POSTs, PUT/PATCH/DELETE, and Authorization are never 'simple' and always preflight." },
  { term: "Opaque response", def: "The result of mode: 'no-cors': status 0, no headers, unreadable body. It deletes your data instead of fixing the permission — a blindfold, not a bypass." },
];

